-- Ginasios com lider humano (entrega 4 do design de 19/10/2026,
-- docs/planos/2026-10-19-ginasios-especialidades-combate-design.md).
--
-- Os numeros (faixas, taxas, limites) repetem src/data/ginasios.ts; o bloco do
-- catalogo (90 ginasios + equipe do lider NPC) e GERADO por
-- src/data/ginasios.test.ts (GERAR_GINASIOS=1), que tambem deriva o par `_dev`.
--
-- QUEM DECIDE A LUTA E O SERVIDOR DO JOGO: `desafiar_ginasio` cobra a taxa e
-- congela as duas equipes; a rota `/ginasio/resolver` roda a luta (motor da
-- arena, semente do desafio) e chama `_aplicar_resultado_ginasio`. O cliente so
-- assiste a mesma luta.

begin;

create table if not exists public.ginasio (
  id text primary key,
  tipo text not null,
  faixa int not null check (faixa in (100, 200, 300, 400, 500)),
  taxa bigint not null check (taxa > 0)
);
alter table public.ginasio enable row level security;
drop policy if exists "ginasio leitura" on public.ginasio;
create policy "ginasio leitura" on public.ginasio for select to authenticated using (true);
grant select on public.ginasio to authenticated;
grant select, insert, update, delete on public.ginasio to service_role;

create table if not exists public.ginasio_lider (
  ginasio_id text primary key references public.ginasio(id) on delete cascade,
  lider_id uuid references public.players(user_id) on delete set null,
  lider_nome text not null,
  equipe jsonb not null,
  mandato_ate timestamptz not null,
  ganhos_mandato bigint not null default 0,
  candidato_id uuid references public.players(user_id) on delete set null,
  candidato_nome text,
  candidato_ticks int,
  candidato_equipe jsonb,
  candidato_em timestamptz
);
alter table public.ginasio_lider enable row level security;
drop policy if exists "lider leitura" on public.ginasio_lider;
create policy "lider leitura" on public.ginasio_lider for select to authenticated using (true);
grant select on public.ginasio_lider to authenticated;
grant select, insert, update, delete on public.ginasio_lider to service_role;

create table if not exists public.ginasio_desafio (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.players(user_id) on delete cascade,
  ginasio_id text not null references public.ginasio(id) on delete cascade,
  tipo text not null check (tipo in ('insignia', 'destronar')),
  taxa bigint not null,
  dia date not null,
  desafiante_nome text not null,
  equipe_desafiante jsonb not null,
  lider_id uuid,
  lider_nome text not null,
  equipe_lider jsonb not null,
  estado text not null default 'aberto' check (estado in ('aberto', 'vitoria', 'derrota', 'empate')),
  ticks int,
  criado_em timestamptz not null default now(),
  resolvido_em timestamptz
);
create index if not exists ginasio_desafio_user_dia on public.ginasio_desafio (user_id, dia);
alter table public.ginasio_desafio enable row level security;
drop policy if exists "desafio leitura propria" on public.ginasio_desafio;
create policy "desafio leitura propria" on public.ginasio_desafio for select to authenticated
  using ((select auth.uid()) = user_id);
grant select on public.ginasio_desafio to authenticated;
grant select, insert, update, delete on public.ginasio_desafio to service_role;

create table if not exists public.player_insignias (
  user_id uuid not null references public.players(user_id) on delete cascade,
  ginasio_id text not null references public.ginasio(id) on delete cascade,
  obtida_em timestamptz not null default now(),
  primary key (user_id, ginasio_id)
);
alter table public.player_insignias enable row level security;
drop policy if exists "insignias leitura" on public.player_insignias;
create policy "insignias leitura" on public.player_insignias for select to authenticated using (true);
grant select on public.player_insignias to authenticated;
grant select, insert, update, delete on public.player_insignias to service_role;

