-- ---------------------------------------------------------------------------
-- Auxiliares
-- ---------------------------------------------------------------------------
-- A equipe ATUAL do jogador, congelada no formato de `PokeDeGinasio`.
create or replace function public._equipe_de_ginasio(p_user uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'species_id', p.species_id,
    'level', p.level,
    'iv', jsonb_build_array(p.iv_hp, p.iv_atk_fis, p.iv_atk_esp, p.iv_def, p.iv_def_esp, p.iv_speed),
    'rarity', p.rarity::text,
    'is_shiny', p.is_shiny,
    'nature', p.nature,
    'active_abilities', to_jsonb(p.active_abilities),
    'golpes_de_maquina', to_jsonb(p.golpes_de_maquina)
  ) order by p.team_slot), '[]'::jsonb)
  from public.pokemon_instances p
  where p.user_id = p_user and p.location = 'team'
$$;
revoke all on function public._equipe_de_ginasio(uuid) from public, anon, authenticated;

-- Motivo de a equipe nao servir, ou null. Mesmas regras de
-- `motivoDeEquipeInvalida` (src/data/ginasios.ts).
create or replace function public._motivo_de_equipe_invalida(p_equipe jsonb, p_tipo text)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_n int := jsonb_array_length(coalesce(p_equipe, '[]'::jsonb));
begin
  if v_n <> 6 then return 'A equipe precisa de 6 POKEs.'; end if;
  if exists (
    select 1 from jsonb_array_elements(p_equipe) e
    group by e->>'species_id' having count(*) > 2
  ) then
    return 'A mesma espécie pode aparecer no máximo 2 vezes.';
  end if;
  if p_tipo is not null and exists (
    select 1 from jsonb_array_elements(p_equipe) e
    left join public.species s on s.id = e->>'species_id'
    where s.id is null or (s.type1::text <> p_tipo and coalesce(s.type2::text, '') <> p_tipo)
  ) then
    return format('Todos os POKEs precisam ser do tipo %s.', p_tipo);
  end if;
  return null;
end;
$$;
revoke all on function public._motivo_de_equipe_invalida(jsonb, text) from public, anon, authenticated;

-- Mandato vencido: assume o melhor tempo de destronar; sem candidato, o lider
-- renova. Roda em toda leitura do estado (preguicoso, sem cron).
create or replace function public._rotacionar_mandatos()
returns void
language sql
security definer
set search_path = public
as $$
  update public.ginasio_lider set
    lider_id = coalesce(candidato_id, lider_id),
    lider_nome = coalesce(candidato_nome, lider_nome),
    equipe = coalesce(candidato_equipe, equipe),
    ganhos_mandato = 0,
    candidato_id = null, candidato_nome = null, candidato_ticks = null, candidato_equipe = null, candidato_em = null,
    mandato_ate = now() + interval '7 days'
  where mandato_ate < now()
$$;
revoke all on function public._rotacionar_mandatos() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- RPCs do jogador
-- ---------------------------------------------------------------------------
create or replace function public.ginasios_estado()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_dia date := public._dia_do_diario();
begin
  if v_user is null then raise exception 'nao autenticado' using errcode = '28000'; end if;
  perform public._rotacionar_mandatos();
  return jsonb_build_object(
    'ginasios', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', g.id, 'tipo', g.tipo, 'faixa', g.faixa, 'taxa', g.taxa,
        'liderId', l.lider_id, 'liderNome', l.lider_nome, 'equipe', l.equipe,
        'mandatoAte', l.mandato_ate,
        'ganhos', case when l.lider_id = v_user then l.ganhos_mandato else null end,
        'candidatoNome', l.candidato_nome, 'candidatoTicks', l.candidato_ticks
      ) order by g.faixa, g.tipo)
      from public.ginasio g join public.ginasio_lider l on l.ginasio_id = g.id
    ), '[]'::jsonb),
    'insignias', coalesce((select jsonb_agg(ginasio_id) from public.player_insignias where user_id = v_user), '[]'::jsonb),
    'desafiosHoje', (select count(*) from public.ginasio_desafio where user_id = v_user and dia = v_dia),
    'pendentes', coalesce((
      select jsonb_agg(id) from public.ginasio_desafio where user_id = v_user and estado = 'aberto'
    ), '[]'::jsonb)
  );
end;
$$;

create or replace function public.desafiar_ginasio(p_ginasio text, p_tipo text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_dia date := public._dia_do_diario();
  v_g public.ginasio;
  v_l public.ginasio_lider;
  v_equipe jsonb;
  v_motivo text;
  v_nome text;
  v_id uuid;
  v_ouro bigint;
begin
  if v_user is null then raise exception 'nao autenticado' using errcode = '28000'; end if;
  if p_tipo not in ('insignia', 'destronar') then raise exception 'Duelo desconhecido.' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtext(v_user::text));
  perform public._rotacionar_mandatos();

  select * into v_g from public.ginasio where id = p_ginasio;
  if v_g.id is null then raise exception 'Ginásio não encontrado.' using errcode = 'P0001'; end if;
  select * into v_l from public.ginasio_lider where ginasio_id = p_ginasio;
  if v_l.lider_id = v_user then raise exception 'Você não pode desafiar o próprio ginásio.' using errcode = 'P0001'; end if;

  if (select count(*) from public.ginasio_desafio where user_id = v_user and dia = v_dia) >= 2 then
    raise exception 'Você já fez os 2 desafios de hoje.' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.ginasio_desafio where user_id = v_user and estado = 'aberto') then
    raise exception 'Termine o desafio em andamento primeiro.' using errcode = 'P0001';
  end if;

  v_equipe := public._equipe_de_ginasio(v_user);
  v_motivo := public._motivo_de_equipe_invalida(v_equipe, case when p_tipo = 'destronar' then v_g.tipo end);
  if v_motivo is not null then raise exception '%', v_motivo using errcode = 'P0001'; end if;

  update public.players set gold = gold - v_g.taxa where user_id = v_user and gold >= v_g.taxa
    returning gold into v_ouro;
  if not found then raise exception 'Ouro insuficiente para a taxa.' using errcode = 'P0001'; end if;

  select trainer_name into v_nome from public.players where user_id = v_user;
  insert into public.ginasio_desafio (user_id, ginasio_id, tipo, taxa, dia, desafiante_nome, equipe_desafiante, lider_id, lider_nome, equipe_lider)
  values (v_user, p_ginasio, p_tipo, v_g.taxa, v_dia, v_nome, v_equipe, v_l.lider_id, v_l.lider_nome, v_l.equipe)
  returning id into v_id;

  return jsonb_build_object('desafioId', v_id, 'teto', v_g.faixa, 'liderNome', v_l.lider_nome, 'liderId', v_l.lider_id,
    'equipeDesafiante', v_equipe, 'equipeLider', v_l.equipe, 'gold', v_ouro);
end;
$$;

-- O lider troca a equipe do ginasio pela equipe ATUAL dele (so POKEs do tipo).
create or replace function public.definir_equipe_do_ginasio(p_ginasio text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_g public.ginasio;
  v_equipe jsonb;
  v_motivo text;
begin
  if v_user is null then raise exception 'nao autenticado' using errcode = '28000'; end if;
  perform pg_advisory_xact_lock(hashtext(v_user::text));
  select * into v_g from public.ginasio where id = p_ginasio;
  if v_g.id is null then raise exception 'Ginásio não encontrado.' using errcode = 'P0001'; end if;
  if not exists (select 1 from public.ginasio_lider where ginasio_id = p_ginasio and lider_id = v_user) then
    raise exception 'Você não é o líder deste ginásio.' using errcode = 'P0001';
  end if;
  v_equipe := public._equipe_de_ginasio(v_user);
  v_motivo := public._motivo_de_equipe_invalida(v_equipe, v_g.tipo);
  if v_motivo is not null then raise exception '%', v_motivo using errcode = 'P0001'; end if;
  update public.ginasio_lider set equipe = v_equipe where ginasio_id = p_ginasio;
  return jsonb_build_object('ok', true, 'mensagem', 'Equipe do ginásio atualizada.');
end;
$$;

-- ---------------------------------------------------------------------------
-- Resultado (so o servidor do jogo, service_role)
-- ---------------------------------------------------------------------------
create or replace function public._aplicar_resultado_ginasio(p_desafio uuid, p_resultado text, p_ticks int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_d public.ginasio_desafio;
  v_g public.ginasio;
  v_repasse bigint;
  v_nova boolean := false;
begin
  if p_resultado not in ('vitoria', 'derrota', 'empate') then raise exception 'resultado invalido' using errcode = 'P0001'; end if;
  -- Serializa com o flush do desafiante (PH-67). O repasse ao lider e incremento.
  perform pg_advisory_xact_lock(hashtext(user_id::text)) from public.ginasio_desafio where id = p_desafio;
  select * into v_d from public.ginasio_desafio where id = p_desafio for update;
  if v_d.id is null then raise exception 'desafio nao encontrado' using errcode = 'P0001'; end if;
  if v_d.estado <> 'aberto' then
    return jsonb_build_object('estado', v_d.estado, 'ticks', v_d.ticks, 'jaResolvido', true);
  end if;
  select * into v_g from public.ginasio where id = v_d.ginasio_id;

  update public.ginasio_desafio set estado = p_resultado, ticks = p_ticks, resolvido_em = now() where id = p_desafio;

  if p_resultado = 'vitoria' and v_d.tipo = 'insignia' then
    insert into public.player_insignias (user_id, ginasio_id) values (v_d.user_id, v_d.ginasio_id)
      on conflict do nothing;
    v_nova := found;
    -- Nivel 10 da Especialidade do tipo pede a insignia (qualquer faixa).
    if v_nova then
      perform public.somar_contadores(v_d.user_id, jsonb_build_object('insignia:' || v_g.tipo, 1));
    end if;
  elsif p_resultado = 'vitoria' and v_d.tipo = 'destronar' then
    -- Disputa do proximo mandato: vale o MENOR tempo; empate fica com quem veio primeiro.
    update public.ginasio_lider set
      candidato_id = v_d.user_id, candidato_nome = v_d.desafiante_nome, candidato_ticks = p_ticks,
      candidato_equipe = v_d.equipe_desafiante, candidato_em = now()
    where ginasio_id = v_d.ginasio_id and (candidato_ticks is null or p_ticks < candidato_ticks);
  elsif p_resultado = 'derrota' and v_d.lider_id is not null and v_d.lider_id <> v_d.user_id then
    -- O lider humano recebe 30% quando vence; o resto da taxa sai do jogo.
    v_repasse := floor(v_d.taxa * 0.3);
    update public.players set gold = gold + v_repasse where user_id = v_d.lider_id;
    update public.ginasio_lider set ganhos_mandato = ganhos_mandato + v_repasse
      where ginasio_id = v_d.ginasio_id and lider_id = v_d.lider_id;
  end if;

  return jsonb_build_object('estado', p_resultado, 'ticks', p_ticks, 'insigniaNova', v_nova);
end;
$$;
revoke all on function public._aplicar_resultado_ginasio(uuid, text, int) from public, anon, authenticated;
grant execute on function public._aplicar_resultado_ginasio(uuid, text, int) to service_role;

commit;
